import { NextResponse } from "next/server";

export async function GET() {
    const privateKey = process.env.FIREBASE_PRIVATE_KEY;

    if (!privateKey) {
        return NextResponse.json({ error: "Private key not found" }, { status: 500 });
    }

    // Format the key
    const formattedKey = privateKey.replace(/\\\\n/g, "\n").replace(/\\n/g, "\n");

    const analysis = {
        originalLength: privateKey.length,
        formattedLength: formattedKey.length,
        hasBeginMarker: formattedKey.includes("-----BEGIN PRIVATE KEY-----"),
        hasEndMarker: formattedKey.includes("-----END PRIVATE KEY-----"),
        startsCorrectly: formattedKey.startsWith("-----BEGIN PRIVATE KEY-----"),
        endsCorrectly: formattedKey.trim().endsWith("-----END PRIVATE KEY-----"),
        lineCount: formattedKey.split('\n').length,
        firstLine: formattedKey.split('\n')[0],
        lastLine: formattedKey.split('\n').slice(-1)[0],
        // Show first 50 chars of formatted key
        preview: formattedKey.substring(0, 100) + "...",
    };

    return NextResponse.json(analysis);
}